#!/usr/bin/env node
/*
 * Offline parity test for the demo's fetch mock (docs-site/demo/mock-api.js).
 *
 *   node docs-site/scripts/test-mock-search.mjs
 *
 * 1. Search parity: for every query in demo/search-expected.json (generated by
 *    snapshot-api.py from the REAL serve.py under the same frozen clock), the
 *    mock must return the same ids, in the same order, with identical
 *    match_score and browse_score. Also checked after restoring every
 *    archived note (queries_full).
 * 2. Initial-state parity: every GET endpoint of the mock equals the python
 *    payload stored in api-snapshot.json.
 * 3. Mutation consistency: archive / restore / confidence / compress-queue
 *    update memories, detail, stats, archived, graph and search together.
 *
 * (Env SNAPSHOT / EXPECTED override the fixture paths.) No network, no python. Regenerate fixtures with `uv run docs-site/scripts/snapshot-api.py`.
 */
import fs from 'node:fs';
import path from 'node:path';
import vm from 'node:vm';
import assert from 'node:assert/strict';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const site = path.resolve(here, '..');
const snapshot = JSON.parse(fs.readFileSync(process.env.SNAPSHOT || path.join(site, 'src/data/api-snapshot.json'), 'utf8'));
const expected = JSON.parse(fs.readFileSync(process.env.EXPECTED || path.join(site, 'demo/search-expected.json'), 'utf8'));

const sandbox = { module: { exports: {} } };
vm.runInNewContext(fs.readFileSync(path.join(site, 'demo/mock-api.js'), 'utf8'), sandbox);
const { createMockApi } = sandbox.module.exports;
// The mock runs in a vm context, so its objects have foreign prototypes;
// round-trip results through JSON so deepEqual compares plain data.
const plain = (v) => (v === undefined ? v : JSON.parse(JSON.stringify(v)));
const fresh = () => {
  const api = createMockApi(structuredClone(snapshot));
  return Object.fromEntries(Object.entries(api).map(([k, fn]) => [k, (...a) => plain(fn(...a))]));
};

let passed = 0;
const failures = [];
function check(name, fn) {
  try {
    fn();
    passed++;
  } catch (e) {
    failures.push(`${name}: ${e.message.split('\n').slice(0, 6).join('\n')}`);
  }
}

// --- 1. search parity ---------------------------------------------------
assert.equal(expected.now, snapshot.meta.now, 'fixtures and snapshot use different frozen clocks');
const slim = (rows) => rows.map((r) => ({ id: r.id, match_score: r.match_score, browse_score: r.browse_score }));

const queries = Object.keys(expected.queries);
assert.ok(queries.length >= 10, 'need at least 10 queries');
const live = fresh();
for (const q of queries) {
  check(`search ${JSON.stringify(q)}`, () => assert.deepEqual(slim(live.search(q)), expected.queries[q]));
}
const restored = fresh();
for (const a of snapshot.endpoints.archived) restored.restore(a.id);
for (const q of queries) {
  check(`search+restored ${JSON.stringify(q)}`, () =>
    assert.deepEqual(slim(restored.search(q)), expected.queries_full[q]));
}
const nonEmpty = queries.filter((q) => expected.queries[q].length).length;
assert.ok(nonEmpty >= 8, `only ${nonEmpty} queries return results; fixtures too weak`);

// --- 2. initial-state parity ---------------------------------------------
const near = (a, b, msg) => {
  // graph scores are unrounded floats; allow 1 ulp-ish libm differences
  if (typeof a === 'number' && typeof b === 'number') return assert.ok(Math.abs(a - b) < 1e-9, `${msg}: ${a} vs ${b}`);
  if (Array.isArray(a) && Array.isArray(b)) {
    assert.equal(a.length, b.length, `${msg}: length`);
    return a.forEach((x, i) => near(x, b[i], `${msg}[${i}]`));
  }
  if (a && b && typeof a === 'object' && typeof b === 'object') {
    assert.deepEqual(Object.keys(a).sort(), Object.keys(b).sort(), `${msg}: keys`);
    return Object.keys(a).forEach((k) => near(a[k], b[k], `${msg}.${k}`));
  }
  assert.equal(a, b, msg);
};
const ep = snapshot.endpoints;
check('GET memories', () => near(live.memories(), ep.memories, 'memories'));
check('GET stats', () => near(live.stats(), ep.stats, 'stats'));
check('GET archived', () => near(live.archived(), ep.archived, 'archived'));
check('GET compress-queue', () => near(live.compressQueue(), ep.compress_queue, 'queue'));
check('GET graph', () => near(live.graph(), ep.graph, 'graph'));
for (const id of Object.keys(ep.memory)) {
  check(`GET memories/${id}`, () => near(live.memory(id), ep.memory[id], id));
}
check('routing + 404', () => {
  const r = live.route('GET', '/ainb-reflect-memory/demo/api/memories/does-not-exist', new URLSearchParams(), {}, {});
  assert.equal(r.status, 404);
  assert.equal(live.route('GET', '/api/nope', new URLSearchParams(), {}, {}).status, 404);
  assert.equal(live.route('POST', '/api/compress-queue', new URLSearchParams(), { ids: [] }, {}).status, 403);
});
check('routing under a base path', () => {
  const r = live.route('GET', '/ainb-reflect-memory/demo/api/search', new URLSearchParams('q=postgres'), {}, {});
  assert.equal(r.status, 200);
  assert.deepEqual(slim(r.body), expected.queries.postgres);
});

// --- 3. mutation consistency -----------------------------------------------
const H = { 'X-Reflect': '1' };
const post = (api, p, body) => api.route('POST', p, new URLSearchParams(), body, H);
const target = ep.memories[0].id;

check('archive moves note everywhere', () => {
  const api = fresh();
  const n = ep.memories.length;
  const searchTerm = Object.keys(expected.queries).find((q) => expected.queries[q].some((r) => r.id === target));
  assert.ok(searchTerm, 'no query hits the target note');
  const res = post(api, `/api/memories/${target}/archive`);
  assert.equal(res.status, 200);
  assert.equal(res.body.archived, true);
  assert.equal(api.memories().length, n - 1);
  assert.ok(!api.memories().some((m) => m.id === target));
  assert.equal(api.memory(target), null);
  assert.equal(api.stats().documents, n - 1);
  assert.ok(api.archived().some((a) => a.id === target));
  assert.ok(!api.graph().nodes.some((x) => x.id === 'm:' + target));
  assert.ok(!api.search(searchTerm).some((r) => r.id === target));
  assert.equal(post(api, `/api/memories/${target}/archive`).status, 400, 'double archive must fail');
  // restore brings it all back, identical to the pristine payloads
  assert.equal(post(api, `/api/memories/${target}/restore`).status, 200);
  near(api.memories(), ep.memories, 'memories after restore');
  near(api.graph(), ep.graph, 'graph after restore');
  near(api.stats(), ep.stats, 'stats after restore');
  assert.deepEqual(slim(api.search(searchTerm)), expected.queries[searchTerm]);
});

check('restoring a shipped-archived note surfaces it', () => {
  if (!ep.archived.length) return;
  const api = fresh();
  const id = ep.archived[0].id;
  assert.equal(post(api, `/api/memories/${id}/restore`).status, 200);
  assert.ok(api.memories().some((m) => m.id === id));
  assert.equal(api.archived().length, ep.archived.length - 1);
  assert.equal(api.stats().documents, ep.memories.length + 1);
  assert.ok(api.memory(id).body.length > 0);
  assert.ok(api.graph().nodes.some((x) => x.id === 'm:' + id));
});

check('confidence edit propagates', () => {
  const api = fresh();
  const before = ep.memories[0].confidence;
  const value = before === 'low' ? 'high' : 'low';
  assert.equal(post(api, `/api/memories/${target}/confidence`, { value }).body.confidence, value);
  assert.equal(api.memory(target).confidence, value);
  assert.equal(api.memories().find((m) => m.id === target).confidence, value);
  assert.equal(api.graph().nodes.find((x) => x.id === 'm:' + target).confidence, value);
  assert.equal(api.stats().confidence[value], (ep.stats.confidence[value] || 0) + 1);
  assert.equal(post(api, `/api/memories/${target}/confidence`, { value: 'bogus' }).status, 400);
});

check('compress queue add + archive dequeues', () => {
  const api = fresh();
  const ids = ep.memories.slice(0, 2).map((m) => m.id);
  const groups0 = api.compressQueue().groups.length;
  const res = post(api, '/api/compress-queue', { ids });
  assert.equal(res.status, 200);
  assert.equal(res.body.groups, groups0 + 1);
  assert.equal(api.compressQueue().groups.length, groups0 + 1);
  assert.equal(post(api, '/api/compress-queue', { ids: [ids[0]] }).status, 400);
  assert.equal(post(api, '/api/compress-queue', { ids: [ids[0], 'ghost'] }).status, 400);
  post(api, `/api/memories/${ids[0]}/archive`);
  const groups = api.compressQueue().groups;
  assert.ok(groups.every((g) => !g.ids.includes(ids[0]) && g.ids.length >= 2));
});

if (failures.length) {
  console.error(`FAIL: ${failures.length} failed, ${passed} passed`);
  for (const f of failures) console.error(' - ' + f);
  process.exit(1);
}
console.log(`ok: ${passed} checks passed (${queries.length} queries x2, ${Object.keys(ep.memory).length} details, mutations)`);
